//! 可导出性检查。
//!
//! 这里做可导出性检查，而不是完整语义分析：列出会让渲染阶段失败或降级的场景、语句与资源。
//! 所有位置都保留 1 起始行号，供编辑器与诊断直接复用。

use std::collections::{BTreeMap, BTreeSet};

use expression::Expression;
use serde::Serialize;
use webgal_language_core::{
    resource::FigureKind,
    sentence::{Error as SentenceError, Sentence, SentenceExt},
};

use crate::{
    VERSION,
    project::Project,
    script::live2d::is_moc3,
    util::{looks_like_audio, path_string},
};

/// 检查结果。
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Inspection {
    /// 导出器版本.
    pub version: String,
    /// 项目摘要.
    pub project: ProjectInfo,
    /// 每个场景的统计.
    pub scenes: Vec<SceneReport>,
    /// 汇总统计.
    pub stats: Stats,
    /// 问题列表.
    pub issues: Vec<Issue>,
}

impl Inspection {
    /// 是否存在 error 级问题.
    pub fn has_errors(&self) -> bool {
        self.issues
            .iter()
            .any(|issue| issue.severity == Severity::Error)
    }
}

/// 项目摘要。
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ProjectInfo {
    pub root: String,
    pub game: String,
    pub title: Option<String>,
    pub template: Option<String>,
    pub template_fonts: Vec<String>,
    pub scene_count: usize,
    /// 舞台宽度 (`game/config.txt` 的 `Stage_Width`, 缺省 2560).
    pub stage_width: u32,
    /// 舞台高度 (`game/config.txt` 的 `Stage_Height`, 缺省 1440).
    pub stage_height: u32,
    /// 项目声明的 WebGAL 版本 (`webgal-engine.json`); 用于选择立绘切换口径.
    pub webgal_version: Option<String>,
}

/// 单个场景的统计。
#[derive(Debug, Clone, Default, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SceneReport {
    pub name: String,
    pub lines: usize,
    pub sentences: usize,
    pub say: usize,
    pub choices: usize,
    pub calls: usize,
    pub commands: BTreeMap<String, usize>,
}

/// 汇总统计。
#[derive(Debug, Clone, Default, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Stats {
    pub scenes: usize,
    pub lines: usize,
    pub sentences: usize,
    pub say: usize,
    pub choices: usize,
    pub calls: usize,
    pub errors: usize,
    pub warnings: usize,
}

/// 问题级别。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Severity {
    Error,
    Warning,
}

/// 单条问题。
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Issue {
    pub severity: Severity,
    pub code: &'static str,
    pub message: String,
    pub scene: Option<String>,
    pub line: Option<usize>,
}

/// 检查整个项目。
pub fn inspect(project: &Project) -> Inspection {
    let mut reports = Vec::new();
    let mut issues = Vec::new();
    let mut stats = Stats::default();

    for (name, entry) in project.scenes() {
        let mut report = SceneReport {
            name: name.to_owned(),
            ..SceneReport::default()
        };

        for (line, info) in entry.sentences() {
            report.lines += 1;
            stats.lines += 1;

            for error in &info.errors {
                let (severity, code) = match error {
                    SentenceError::ArgumentObsolete(..) => (Severity::Warning, "WG_DEPRECATED"),
                    SentenceError::ArgumentRepeated(..) => (Severity::Warning, "WG_DUPLICATE_ARG"),
                    _ => (Severity::Error, "WG_PARSE"),
                };
                push_issue(&mut issues, severity, code, error.to_string(), name, line);
            }

            if !matches!(info.sentence, Sentence::Comment(_)) {
                report.sentences += 1;
                stats.sentences += 1;
            }
            *report
                .commands
                .entry(info.sentence.command().to_owned())
                .or_default() += 1;

            check_condition(&info.sentence, name, line, &mut issues);

            match &info.sentence {
                Sentence::Say(sentence) => {
                    report.say += 1;
                    stats.say += 1;

                    let mut variables = BTreeSet::new();
                    for text in &sentence.content {
                        variables.extend(template_variables(text));
                    }
                    if let Some(speaker) = &sentence.speaker {
                        variables.extend(template_variables(speaker));
                    }
                    if !variables.is_empty() {
                        push_issue(
                            &mut issues,
                            Severity::Error,
                            "WG_VARIABLE_TEXT",
                            format!("文本插值需要变量, 暂不支持: {}", join_variables(&variables)),
                            name,
                            line,
                        );
                    }
                    if let Some(vocal) = &sentence.vocal
                        && looks_like_audio(vocal)
                    {
                        check_asset(project, name, line, "vocal", vocal, "语音", &mut issues);
                    }
                }
                Sentence::ChangeBackground(sentence) => {
                    if let Some(background) = &sentence.background {
                        check_asset(
                            project,
                            name,
                            line,
                            "background",
                            background,
                            "背景",
                            &mut issues,
                        );
                    }
                }
                Sentence::ChangeFigure(sentence) => {
                    if let Some(figure) = &sentence.figure {
                        let (kind, path) = FigureKind::from_path(figure);
                        if kind != FigureKind::Image && kind != FigureKind::Live2d {
                            push_issue(
                                &mut issues,
                                Severity::Error,
                                "WG_FIGURE_KIND",
                                format!(
                                    "当前只支持图片/Live2D 立绘, 当前立绘类型为 {kind:?}: {path}"
                                ),
                                name,
                                line,
                            );
                        }
                        if kind == FigureKind::Live2d
                            && let Some(file) = project.asset_path("figure", path)
                            && !is_moc3(&file)
                        {
                            push_issue(
                                &mut issues,
                                Severity::Error,
                                "WG_LIVE2D_CUBISM2",
                                format!("不支持 Cubism 2 模型 (只有 .moc): {path}; 请使用 moc3"),
                                name,
                                line,
                            );
                        }
                        check_asset(project, name, line, "figure", path, "立绘", &mut issues);
                    }
                }
                Sentence::Bgm(sentence) => {
                    if let Some(bgm) = &sentence.bgm {
                        check_asset(project, name, line, "bgm", bgm, "BGM", &mut issues);
                    }
                }
                Sentence::PlayEffect(sentence) => {
                    if let Some(vocal) = &sentence.vocal
                        && looks_like_audio(vocal)
                    {
                        check_asset(project, name, line, "vocal", vocal, "音效", &mut issues);
                    }
                }
                Sentence::PlayVideo(sentence) => {
                    check_asset(
                        project,
                        name,
                        line,
                        "video",
                        &sentence.video,
                        "视频",
                        &mut issues,
                    );
                }
                Sentence::Intro(sentence) => {
                    let mut variables = BTreeSet::new();
                    for text in &sentence.content {
                        variables.extend(template_variables(text));
                    }
                    if !variables.is_empty() {
                        push_issue(
                            &mut issues,
                            Severity::Error,
                            "WG_VARIABLE_TEXT",
                            format!(
                                "intro 文本插值需要变量, 暂不支持: {}",
                                join_variables(&variables)
                            ),
                            name,
                            line,
                        );
                    }
                    if let Some(image) = &sentence.background_image {
                        check_asset(
                            project,
                            name,
                            line,
                            "background",
                            image,
                            "intro 背景",
                            &mut issues,
                        );
                    }
                }
                Sentence::Choose(sentence) => {
                    report.choices += 1;
                    stats.choices += 1;
                    for choice in &sentence.choices {
                        for condition in [&choice.show, &choice.enable] {
                            if let Some(variables) = condition_variables(condition) {
                                push_issue(
                                    &mut issues,
                                    Severity::Error,
                                    "WG_VARIABLE_CHOICE",
                                    format!(
                                        "选项条件依赖变量, 暂不支持: {}",
                                        join_variables(&variables)
                                    ),
                                    name,
                                    line,
                                );
                            }
                        }
                        let mut variables = template_variables(&choice.prompt);
                        if let Some(target) = &choice.target {
                            variables.extend(template_variables(target));
                        }
                        if !variables.is_empty() {
                            push_issue(
                                &mut issues,
                                Severity::Error,
                                "WG_VARIABLE_TEXT",
                                format!(
                                    "选项文本插值需要变量, 暂不支持: {}",
                                    join_variables(&variables)
                                ),
                                name,
                                line,
                            );
                        }
                    }
                }
                Sentence::CallScene(sentence) => {
                    report.calls += 1;
                    stats.calls += 1;
                    if !sentence.variables.is_empty() || sentence.write_return_to.is_some() {
                        push_issue(
                            &mut issues,
                            Severity::Error,
                            "WG_VARIABLE_CALL",
                            "callScene 传参/返回值依赖变量, 暂不支持".to_owned(),
                            name,
                            line,
                        );
                    }
                    check_scene(project, name, line, &sentence.scene, &mut issues);
                }
                Sentence::ChangeScene(sentence) => {
                    report.calls += 1;
                    stats.calls += 1;
                    check_scene(project, name, line, &sentence.scene, &mut issues);
                }
                Sentence::Return(sentence) => {
                    if let Some(variables) = expression_variables(&sentence.value) {
                        push_issue(
                            &mut issues,
                            Severity::Error,
                            "WG_VARIABLE_RETURN",
                            format!(
                                "return 表达式依赖变量, 暂不支持: {}",
                                join_variables(&variables)
                            ),
                            name,
                            line,
                        );
                    }
                }
                Sentence::SetVariable(sentence) => {
                    push_issue(
                        &mut issues,
                        Severity::Error,
                        "WG_VARIABLE_SET",
                        format!("暂不支持变量: {}", sentence.expression.0),
                        name,
                        line,
                    );
                }
                Sentence::GetUserInput(sentence) => {
                    push_issue(
                        &mut issues,
                        Severity::Error,
                        "WG_USER_INPUT",
                        format!("暂不支持 getUserInput: {}", sentence.variable),
                        name,
                        line,
                    );
                }
                Sentence::ShowVariables(_) => {
                    push_issue(
                        &mut issues,
                        Severity::Error,
                        "WG_VARIABLE_SHOW",
                        "暂不支持 showVars".to_owned(),
                        name,
                        line,
                    );
                }
                _ => {}
            }
        }

        stats.scenes += 1;
        reports.push(report);
    }

    for issue in &issues {
        match issue.severity {
            Severity::Error => stats.errors += 1,
            Severity::Warning => stats.warnings += 1,
        }
    }

    let template = project.template();
    let (stage_width, stage_height) = project.stage_size();
    Inspection {
        version: VERSION.to_owned(),
        project: ProjectInfo {
            root: path_string(project.root()),
            game: path_string(project.game_dir()),
            title: project.config().title.clone(),
            template: template.and_then(|template| template.name.clone()),
            template_fonts: template
                .map(|template| template.fonts.clone())
                .unwrap_or_default(),
            scene_count: stats.scenes,
            stage_width,
            stage_height,
            webgal_version: project.webgal_version(),
        },
        scenes: reports,
        stats,
        issues,
    }
}

fn check_condition(sentence: &Sentence, scene: &str, line: usize, issues: &mut Vec<Issue>) {
    if let Some(variables) = sentence.condition().and_then(expression_variables) {
        push_issue(
            issues,
            Severity::Error,
            "WG_VARIABLE_WHEN",
            format!(
                "when 条件依赖变量, 暂不支持: {}",
                join_variables(&variables)
            ),
            scene,
            line,
        );
    }
}

fn check_scene(project: &Project, scene: &str, line: usize, target: &str, issues: &mut Vec<Issue>) {
    if project.scene(target).is_none() {
        push_issue(
            issues,
            Severity::Error,
            "WG_SCENE_MISSING",
            format!("场景不存在: {target}"),
            scene,
            line,
        );
    }
}

fn check_asset(
    project: &Project,
    scene: &str,
    line: usize,
    kind_dir: &str,
    raw: &str,
    label: &str,
    issues: &mut Vec<Issue>,
) {
    if project.asset_path(kind_dir, raw).is_none() {
        push_issue(
            issues,
            Severity::Error,
            "WG_ASSET_MISSING",
            format!("{label}资源不存在: {raw}"),
            scene,
            line,
        );
    }
}

fn expression_variables(expression: &Expression) -> Option<BTreeSet<String>> {
    let variables: BTreeSet<String> = expression
        .variables()
        .into_iter()
        .map(str::to_owned)
        .collect();
    (!variables.is_empty()).then_some(variables)
}

fn condition_variables(condition: &Option<Expression>) -> Option<BTreeSet<String>> {
    condition.as_ref().and_then(expression_variables)
}

/// 找出 `{name}` 形式的变量插值.
fn template_variables(text: &str) -> BTreeSet<String> {
    let mut variables = BTreeSet::new();
    let mut rest = text;
    while let Some(start) = rest.find('{') {
        rest = &rest[start + 1..];
        let Some(end) = rest.find('}') else {
            break;
        };
        let name = &rest[..end];
        if is_identifier(name) {
            variables.insert(name.to_owned());
        }
        rest = &rest[end + 1..];
    }
    variables
}

fn is_identifier(value: &str) -> bool {
    let mut characters = value.chars();
    let Some(first) = characters.next() else {
        return false;
    };
    (first.is_ascii_alphabetic() || first == '_')
        && characters.all(|character| character.is_ascii_alphanumeric() || character == '_')
}

fn join_variables(variables: &BTreeSet<String>) -> String {
    variables.iter().cloned().collect::<Vec<_>>().join(", ")
}

fn push_issue(
    issues: &mut Vec<Issue>,
    severity: Severity,
    code: &'static str,
    message: String,
    scene: &str,
    line: usize,
) {
    issues.push(Issue {
        severity,
        code,
        message,
        scene: Some(scene.to_owned()),
        line: Some(line),
    });
}
